(* Expected time < 8.00s *)
(* A deep reduction prefix: a chain of 16000 constant aliases, so the
   guard's prefix walk delta-unfolds 16000 deep before it reaches the
   recursive binder. The walk must do this with bounded OCaml stack (its
   reduction machine keeps pending work on the heap). The substitution walk
   measured in review (ReviewSW/DeepSW F3) recursed on the OCaml stack along
   the reduction and overflowed it at this depth, crashing the process
   instead of finishing; a regression to it fails this test. On this machine
   the guard runs in well under a second. Native compilation is off
   (rocq-prover/rocq#16599). *)
